import java.util.Scanner;

public class Main {
    static long[] sequence = new long[18];
    static int minSteps = Integer.MAX_VALUE;

    static void explore(int steps, long remaining, int index) {
        if (steps > minSteps)
            return;
        if (remaining == 0) {
            minSteps = Math.min(minSteps, steps);
            return;
        }
        int quotient = (int) (remaining / sequence[index]);
        explore(steps + index * quotient, remaining - quotient * sequence[index], index - 1);
        explore(steps + quotient * index, quotient * sequence[index] - remaining, index - 1);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long val = scanner.nextLong();
        sequence[1] = 1;
        for (int i = 2; i < 18; i++) {
            sequence[i] = sequence[i - 1] * 10 + 1;
        }
        long temp = val;
        minSteps = 0;
        while (temp > 0) {
            for (int i = 1; i < 18; i++) {
                if (sequence[i] > temp) {
                    minSteps += (i - 1);
                    temp -= sequence[i - 1];
                    break;
                }
            }
        }
        explore(0, val, 16);
        System.out.println(minSteps);
        scanner.close();
    }
}
